package br.com.sussmartcare.triage.domain; import static org.assertj.core.api.Assertions.assertThat; import java.util.*; import org.junit.jupiter.api.Test; class TriageEventSourcingTest{@Test void reconstructsDecisionHistory(){var t=Triage.start(UUID.randomUUID());t.assessment(ClinicalPriority.HIGH,.8,"demo","model","1");UUID professional=UUID.randomUUID();t.confirm(ClinicalPriority.MEDIUM,professional);var events=t.pullChanges();var rebuilt=Triage.rehydrate(events);assertThat(rebuilt.getAiRecommendation()).isEqualTo(ClinicalPriority.HIGH);assertThat(rebuilt.getFinalPriority()).isEqualTo(ClinicalPriority.MEDIUM);assertThat(rebuilt.getDecidedBy()).isEqualTo(professional);assertThat(rebuilt.getVersion()).isEqualTo(3);}}
